export const getReturnIssueUrl = (id: number,) => {




  return `/api/issues/${id}/return`
}

/**
 * @summary Return an issued book
 */
export const returnIssue = async (id: number, options?: Parameters<typeof customFetch>[1]): Promise<Issue> => {

  return customFetch<Issue>(getReturnIssueUrl(id),
  {
    ...options,
    method: 'POST'


  }
);}





